// Some portions generated by Codex
import { useLayoutEffect, useMemo, useRef, useState } from "react";
import type { KeyboardEvent } from "react";
import { collectionEntries } from "./graph-collections.ts";
import type { CollectionAnalysis, CollectionEntry } from "./graph-collections.ts";
import type { GraphNode } from "./graph-types.ts";
import { compactTerm } from "./graph-terms.ts";
import {
  COLLECTION_DETAILS_ROW_HEIGHT,
  COLLECTION_DETAILS_VIEW_HEIGHT,
  collectionMemberWindow,
  collectionSummary,
  canToggleCollectionView,
} from "./collection-presentation.ts";
import "./collection-details.css";

export type CollectionDetailsProps = {
  analysis: CollectionAnalysis;
  nodes: ReadonlyMap<string, GraphNode>;
  headId: string;
  expanded: boolean;
  connected: boolean;
  loading: boolean;
  canLoad: boolean;
  continuationUnavailableReason?: string;
  onToggleStructure: () => void;
  onToggleConnections: () => void;
  onLoad: () => void;
  onMember: (memberId: string, cellId: string) => void;
  onCell: (cellId: string) => void;
};

/** Ordered occurrences keep member identity separate from the RDF cell that stores that occurrence. */
function MemberRows({ entries, totalCount, nodes, analysis, onMember, onCell }: {
  entries: readonly CollectionEntry[];
  totalCount: number | null;
  nodes: ReadonlyMap<string, GraphNode>;
  analysis: CollectionAnalysis;
  onMember: CollectionDetailsProps["onMember"];
  onCell: CollectionDetailsProps["onCell"];
}) {
  const [scrollTop, setScrollTop] = useState(0);
  const viewport = useRef<HTMLDivElement>(null);
  const pendingFocus = useRef<number | null>(null);
  const { start, end } = collectionMemberWindow(entries.length, scrollTop);
  useLayoutEffect(() => {
    if (pendingFocus.current === null) return;
    viewport.current?.querySelector<HTMLButtonElement>(`[data-member-position="${pendingFocus.current}"]`)?.focus({ preventScroll: true });
    pendingFocus.current = null;
  }, [start, end, scrollTop]);

  const moveFocus = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const next = event.key === "ArrowDown" ? Math.min(entries.length - 1, index + 1)
      : event.key === "ArrowUp" ? Math.max(0, index - 1)
        : event.key === "Home" ? 0 : event.key === "End" ? entries.length - 1 : null;
    if (next === null || !viewport.current) return;
    event.preventDefault();
    const top = next * COLLECTION_DETAILS_ROW_HEIGHT;
    const visibleHeight = viewport.current.clientHeight;
    const nextScroll = Math.max(0, top < viewport.current.scrollTop ? top
      : top + COLLECTION_DETAILS_ROW_HEIGHT > viewport.current.scrollTop + visibleHeight
        ? top + COLLECTION_DETAILS_ROW_HEIGHT - visibleHeight : viewport.current.scrollTop);
    viewport.current.scrollTop = nextScroll;
    const button = viewport.current.querySelector<HTMLButtonElement>(`[data-member-position="${entries[next].position}"]`);
    if (button) button.focus({ preventScroll: true });
    else pendingFocus.current = entries[next].position;
    setScrollTop(nextScroll);
  };

  return (
    <div
      ref={viewport}
      className="collection-details-members"
      role="list"
      aria-label="Collection members in order"
      style={{ height: Math.min(COLLECTION_DETAILS_VIEW_HEIGHT, entries.length * COLLECTION_DETAILS_ROW_HEIGHT) }}
      onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
    >
      <div className="collection-details-spacer" role="presentation" style={{ height: entries.length * COLLECTION_DETAILS_ROW_HEIGHT }}>
        {entries.slice(start, end).map((entry, offset) => {
          const node = nodes.get(entry.memberId);
          const label = node?.termValue ?? node?.label ?? compactTerm(entry.memberId);
          const nested = analysis.collections.get(entry.memberId);
          const metadata = node?.language ? `@${node.language}${node.direction ? `--${node.direction}` : ""}`
            : node?.datatype ? compactTerm(node.datatype, 56)
              : nested ? collectionSummary(nested) : node?.kind === "blank" ? "Blank node"
                : node?.kind === "literal" ? "Literal" : "Resource";
          const title = node?.kind === "literal" ? `${label}\n${node.language ? metadata : node.datatype ?? "Literal"}`
            : `${label}\n${entry.memberId}`;
          return (
            <div
              className="collection-details-row"
              role="listitem"
              key={entry.cellId}
              aria-posinset={entry.position}
              aria-setsize={totalCount ?? -1}
              data-collection-index={entry.position}
              data-cell-id={entry.cellId}
              style={{ height: COLLECTION_DETAILS_ROW_HEIGHT, top: (start + offset) * COLLECTION_DETAILS_ROW_HEIGHT }}
            >
              <span className="collection-details-position" aria-hidden="true">{entry.position}</span>
              <button
                type="button"
                className="collection-details-member"
                data-member-id={entry.memberId}
                data-member-position={entry.position}
                aria-label={`Select member ${entry.position}: ${label}`}
                title={title}
                onClick={() => onMember(entry.memberId, entry.cellId)}
                onKeyDown={(event) => moveFocus(event, start + offset)}
              >
                <span dir={node?.direction}>{node?.kind === "literal" ? `"${label}"` : label}</span>
                <small>{metadata}</small>
              </button>
              <button
                type="button"
                className="collection-details-cell"
                aria-label={`Inspect cell ${entry.position}`}
                title={`Inspect the RDF cell ${entry.cellId}`}
                onClick={() => onCell(entry.cellId)}
              >Cell</button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/** The analysis describes only statements already loaded into this graph, including currently hidden values. */
export function CollectionDetails(props: CollectionDetailsProps) {
  const { analysis, nodes, headId, expanded, connected, loading, canLoad, continuationUnavailableReason, onToggleStructure, onToggleConnections, onLoad, onMember, onCell } = props;
  const info = analysis.collections.get(headId);
  const entries = useMemo(() => info ? collectionEntries(analysis, headId, 0, info.loadedCount) : [], [analysis, headId, info]);
  if (!info) return null;
  const status = info.status === "complete" ? "Complete in this view"
    : info.status === "partial" ? "Incomplete in this view"
      : info.status === "cycle" ? "Cycle in list structure" : "Ambiguous list structure";
  return (
    <section className="collection-details" aria-label="RDF collection">
      <header>
        <h4>{collectionSummary(info)}</h4>
        <p className="collection-details-status" data-status={info.status}>{status}</p>
      </header>
      <p className="collection-details-note">
        {info.status === "complete" ? "The loaded sequence reaches rdf:nil. Only loaded statements were checked." : info.reason ?? "More statements are needed to determine this list's members."}
      </p>
      {info.status === "complete" && !info.collapsible && info.reason ? <p className="collection-details-note">{info.reason}</p> : null}
      {canToggleCollectionView(analysis, headId) ? (
        <div className="collection-details-actions">
          <button type="button" className="workbench-action workbench-action--secondary" aria-pressed={expanded} onClick={onToggleStructure}>
            {expanded ? "Show collection" : "Show RDF structure"}
          </button>
          {info.loadedCount ? <button type="button" className="workbench-action workbench-action--secondary" aria-pressed={connected} disabled={expanded} onClick={onToggleConnections}>
            {connected ? "Hide member connections" : "Show member connections"}
          </button> : null}
        </div>
      ) : null}
      {entries.length ? <MemberRows key={headId} entries={entries} totalCount={info.count} nodes={nodes} analysis={analysis} onMember={onMember} onCell={onCell} /> : null}
      {info.status === "partial" ? (
        <div className="collection-details-continuation">
          <button type="button" className="workbench-action workbench-action--secondary" disabled={loading || !canLoad} onClick={onLoad}>
            {loading ? "Loading continuation…" : "Load continuation"}
          </button>
          {!canLoad ? <p className="collection-details-note">{continuationUnavailableReason ?? "This blank node has no reusable repository identifier. Expand its owning resource or load a larger view to continue."}</p> : null}
        </div>
      ) : null}
    </section>
  );
}
